import json
from pathlib import Path

spec = TASK["public"]["specification"]
X, Y = spec["inputs"], spec["outputs"]
assert len(X) == len(Y) == 1024

ones = {sum(int(bit) << (9-i) for i, bit in enumerate(row))
        for row, y in zip(X, Y) if int(y)}

if not ones:
    terms = []
elif len(ones) == 1024:
    terms = [None]  # constant true
else:
    # Quine–McCluskey prime implicants: (fixed-bit mask, fixed-bit value).
    current = {(1023, m) for m in ones}
    prime_set = set()
    while current:
        used, merged = set(), set()
        for mask, value in current:
            for bit in range(10):
                flag = 1 << bit
                if mask & flag and not (value & flag):
                    other = (mask, value | flag)
                    if other in current:
                        used.update(((mask, value), other))
                        merged.add((mask ^ flag, value & ~flag))
        prime_set.update(current - used)
        current = merged

    candidates = []
    for mask, value in prime_set:
        covered = {m for m in ones if (m & mask) == value}
        if covered:
            candidates.append((mask, value, covered))

    uncovered = set(ones)
    terms = []
    while uncovered:
        mask, value, covered = max(
            (c for c in candidates if c[2] & uncovered),
            key=lambda c: (len(c[2] & uncovered), -c[0].bit_count())
        )
        terms.append((mask, value))
        uncovered -= covered

if len(terms) > 32:
    raise RuntimeError(f"Exact SOP cover requires {len(terms)} terms; only 32 slots")

patch = []
def setv(tensor, index, value):
    patch.append({"op": "set", "tensor": tensor, "index": list(index), "value": float(value)})

# Keep inputs available at each stage; computed terms use the first channel
# in each triple, so each signal is read as h[j]+h[j+1]-h[j+2].
for w in ("w0", "w1", "w2", "w3"):
    for i in range(10):
        setv(w, (i, i), 1)

if terms == [None]:
    setv("bias", (1,), 1)
else:
    for k, term in enumerate(terms):
        layer = k // 8
        row = 10 + 3 * (k % 8)
        w, b = (("w0", "b0"), ("w1", "b1"),
                ("w2", "b2"), ("w3", "b3"))[layer]
        if term is None:
            setv(b, (row,), 1)
        else:
            mask, value = term
            positive_count = 0
            for bit in range(10):
                flag = 1 << (9-bit)
                if mask & flag:
                    if value & flag:
                        setv(w, (row, bit), 1)
                        positive_count += 1
                    else:
                        setv(w, (row, bit), -1)
            setv(b, (row,), 1-positive_count)
        setv("out", (1, row), 1)

sub = {"patch": patch}
check_submission(sub)
Path("/work/submission.json").write_text(json.dumps(sub))
